    private static StackPanel Form()=>new(){Spacing=15,MinWidth=280,MaxWidth=560};
    private static TextBlock Note(string text)=>new(){Text=text,FontSize=12,TextWrapping=TextWrapping.Wrap,Opacity=.75};
    private static FrameworkElement Field(string label,FrameworkElement control){var panel=new StackPanel{Spacing=7};panel.Children.Add(new TextBlock{Text=label,FontSize=12});panel.Children.Add(control);return panel;}
    private static ComboBox Choice(string[] labels,int selected){var box=new ComboBox{ItemsSource=labels,SelectedIndex=Math.Clamp(selected,0,labels.Length-1),HorizontalAlignment=HorizontalAlignment.Stretch};return box;}
    private ContentDialog Dialog(string title,UIElement content,string primary="保存")=>new(){XamlRoot=XamlRoot,RequestedTheme=RequestedTheme,Title=title,Content=new ScrollViewer{Content=content,MaxHeight=Math.Max(250,Math.Min(650,ActualHeight-180)),VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled},PrimaryButtonText=primary,CloseButtonText="返回",DefaultButton=ContentDialogButton.None};
