    {
        dialog.PrimaryButtonClick+=async(_,args)=>{var defer=args.GetDeferral();try{await save();}catch(Exception error){args.Cancel=true;status.Text=error.Message;}finally{defer.Complete();}};await dialog.ShowAsync();
    }
